import React from 'react';
import { Link, useParams } from 'react-router-dom';
import { CheckCircle2, Package, ArrowRight } from 'lucide-react';

function OrderSuccess() {
  const { orderId } = useParams();

  let order = null;

  try {
    const orders = JSON.parse(
      localStorage.getItem('craftlanka_orders') || '[]'
    );

    order = Array.isArray(orders)
      ? orders.find((item) => item.id === orderId)
      : null;
  } catch {
    order = null;
  }

  if (!order) {
    return (
      <main className="order-success-page">
        <Package size={44} />
        <h1>Order details not found</h1>
        <p>This demo order may not exist in this browser.</p>
        <Link to="/products" className="btn-primary">
          Continue Shopping
        </Link>
      </main>
    );
  }

  return (
    <main className="order-success-page">
      <div className="order-success-icon">
        <CheckCircle2 size={46} />
      </div>

      <p className="eyebrow">THANK YOU FOR SUPPORTING LOCAL CRAFTS</p>

      <h1>Your demo order is placed!</h1>

      <p className="order-success-message">
        Thank you, {order.customer.fullName}. Your order details have been
        saved in this browser for demonstration purposes.
      </p>

      <section className="order-success-card">
        <div>
          <span>Order Reference</span>
          <strong>{order.id}</strong>
        </div>

        <div>
          <span>Order Status</span>
          <strong>{order.status}</strong>
        </div>

        <div>
          <span>Payment Method</span>
          <strong>
            {order.paymentMethod === 'cod' ? 'Cash on Delivery' : 'Bank Transfer'}
          </strong>
        </div>

        <div>
          <span>Total</span>
          <strong>LKR {order.total.toLocaleString('en-LK')}</strong>
        </div>
      </section>

      <div className="order-success-items">
        <h2>Items ordered</h2>

        {order.items.map((item, index) => (
          <div className="order-success-item" key={`${item.id}-${index}`}>
            <img src={item.image} alt={item.name} />
            <div>
              <strong>{item.name}</strong>
              <span>Quantity: {item.quantity}</span>
            </div>
            <strong>
              LKR {(item.price * item.quantity).toLocaleString('en-LK')}
            </strong>
          </div>
        ))}
      </div>

      <div className="order-success-actions">
        <Link to="/products" className="btn-primary">
          Continue Shopping <ArrowRight size={17} />
        </Link>
        <Link to="/artisans" className="order-success-secondary">
          Meet Our Artisans
        </Link>
      </div>

      <p className="order-success-disclaimer">
        Demo only: no real payment was processed and no delivery has been arranged.
      </p>
    </main>
  );
}

export default OrderSuccess;
